  vec3 BINORMAL = jv_v_binormal;
  vec3 VIEW = normalize(-VERTEX);
  vec2 UV = jv_v_uv;
  vec2 UV2 = jv_v_uv2;
  vec4 COLOR = jv_v_color;
  vec4 FRAGCOORD = gl_FragCoord;
  vec2 SCREEN_UV = gl_FragCoord.xy / jv_viewport;
  bool FRONT_FACING = gl_FrontFacing;
  vec2 POINT_COORD = vec2(0.0);
  vec3 ALBEDO = vec3(1.0);
  float ALPHA = 1.0;
  float ALPHA_SCISSOR_THRESHOLD = 0.5;
  float ALPHA_HASH_SCALE = 1.0;
  float ALPHA_ANTIALIASING_EDGE = 0.0;
  vec2 ALPHA_TEXTURE_COORDINATE = vec2(0.0);
  vec3 EMISSION = vec3(0.0);
  float ROUGHNESS = 1.0;
  float METALLIC = 0.0;
  float SPECULAR = 0.5;
  float RIM = 0.0;
  float RIM_TINT = 0.0;
  float CLEARCOAT = 0.0;
  float CLEARCOAT_ROUGHNESS = 0.0;
  float ANISOTROPY = 0.0;
  vec2 ANISOTROPY_FLOW = vec2(0.0);
  float SSS_STRENGTH = 0.0;
  vec3 BACKLIGHT = vec3(0.0);
  float AO = 1.0;
  float AO_LIGHT_AFFECT = 0.0;
  vec3 NORMAL_MAP = vec3(0.5, 0.5, 1.0);
  float NORMAL_MAP_DEPTH = 1.0;
  vec3 LIGHT_VERTEX = VERTEX;
  float DEPTH = gl_FragCoord.z;
  vec4 FOG = vec4(0.0);
  vec4 RADIANCE = vec4(0.0);
  vec4 IRRADIANCE = vec4(0.0);
  {

	float u = UV.x;
	float v = (UV.y - 0.5) * 2.0;

	float w = u < head ? smoothstep(0.0, head, u) : 1.0 - smoothstep(head, 1.0, u);
	w = pow(w, 0.6);
	float aa = fwidth(v) * 1.5;
	float a = 1.0 - smoothstep(w - aa, w + aa, abs(v));
	if (a <= 0.001) {
		discard;
	}
	ALBEDO = jv_out(jv_in(tint.rgb));
	ALPHA = a * tint.a;

  }
  vec3 jv_col = ALBEDO;
  jv_col += EMISSION;
  jv_FragColor = vec4(jv_col, ALPHA);
}
